<script>
import BaseComponent from '@primevue/core/basecomponent';
import SidebarSpacerStyle from 'primevue/sidebarspacer/style';

export default {
    name: 'BaseSidebarSpacer',
    extends: BaseComponent,
    props: {
        as: {
            type: [String, Object],
            default: 'DIV'
        },
        asChild: {
            type: Boolean,
            default: false
        }
    },
    style: SidebarSpacerStyle,
    provide() {
        return {
            $pcSidebarSpacer: this,
            $parentInstance: this
        };
    }
};
</script>
